import re
from typing import Optional


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.split('\n')
    sections: dict[str, dict[str, str]] = {}
    current_section: Optional[str] = None
    last_key: Optional[str] = None
    i = 0

    while i < len(lines):
        line = lines[i]

        # Check for continuation line
        if line and line[0] in (' ', '\t') and last_key is not None and current_section is not None:
            stripped = line.strip()
            if stripped:
                sections[current_section][last_key] += '\n' + stripped
            i += 1
            continue

        stripped_line = line.strip()

        # Skip empty lines
        if not stripped_line:
            i += 1
            continue

        # Skip comment lines
        if stripped_line[0] in (';', '#'):
            i += 1
            continue

        # Check for section header
        if stripped_line.startswith('[') and ']' in stripped_line:
            bracket_end = stripped_line.index(']')
            section_name = stripped_line[1:bracket_end].strip()
            current_section = section_name
            if current_section not in sections:
                sections[current_section] = {}
            last_key = None
            i += 1
            continue

        # Check for key-value pair
        sep_pos = -1
        for j, char in enumerate(stripped_line):
            if char in ('=', ':'):
                sep_pos = j
                break

        if sep_pos == -1:
            raise ValueError(f"Malformed line: {line}")

        if current_section is None:
            raise ValueError("Key before any section header")

        key = stripped_line[:sep_pos].strip().lower()
        value_part = stripped_line[sep_pos + 1:]

        value = _process_value(value_part)

        sections[current_section][key] = value
        last_key = key

        i += 1

    return _interpolate_sections(sections)


def _process_value(value_part: str) -> str:
    value_part = value_part.lstrip()

    if not value_part:
        return ''

    if value_part.startswith('"'):
        i = 1
        while i < len(value_part):
            if value_part[i] == '"':
                return value_part[1:i]
            elif value_part[i] == '\\' and i + 1 < len(value_part):
                i += 2
            else:
                i += 1
        return value_part[1:]

    result = []
    i = 0
    while i < len(value_part):
        if value_part[i] in (' ', '\t') and i + 1 < len(value_part):
            if value_part[i + 1] in (';', '#'):
                break
        result.append(value_part[i])
        i += 1

    return ''.join(result).strip()


def _interpolate_sections(sections: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {}
    default_keys = sections.get('DEFAULT', {})

    for section_name, section_data in sections.items():
        if section_name == 'DEFAULT':
            continue

        merged = {**default_keys, **section_data}
        interpolated: dict[str, str] = {}
        for key, value in merged.items():
            interpolated[key] = _interpolate_value(value, section_name, merged, set(), sections)
        result[section_name] = interpolated

    return result


def _interpolate_value(
    value: str,
    section_name: str,
    all_values: dict[str, str],
    visiting: set[tuple[str, str]],
    sections: dict[str, dict[str, str]]
) -> str:
    result = []
    i = 0

    while i < len(value):
        if value[i:i+2] == '${':
            end = value.find('}', i + 2)
            if end == -1:
                raise ValueError(f"Unclosed interpolation: {value}")

            ref = value[i + 2:end]

            if ':' in ref:
                ref_parts = ref.split(':', 1)
                ref_section = ref_parts[0]
                ref_key = ref_parts[1].lower()

                if ref_section not in sections:
                    raise KeyError(f"Section '{ref_section}' not found")

                target_section = sections[ref_section]
                if ref_key not in target_section:
                    raise KeyError(f"Key '{ref_key}' not found in section '{ref_section}'")

                cycle_key = (ref_section, ref_key)
                if cycle_key in visiting:
                    raise ValueError(f"Interpolation cycle detected: {ref_section}:{ref_key}")

                visiting.add(cycle_key)
                try:
                    substituted = _interpolate_value(
                        target_section[ref_key],
                        ref_section,
                        target_section,
                        visiting,
                        sections
                    )
                finally:
                    visiting.discard(cycle_key)

                result.append(substituted)
            else:
                ref_key = ref.lower()

                if ref_key not in all_values:
                    raise KeyError(f"Key '{ref_key}' not found")

                cycle_key = (section_name, ref_key)
                if cycle_key in visiting:
                    raise ValueError(f"Interpolation cycle detected: {section_name}:{ref_key}")

                visiting.add(cycle_key)
                try:
                    substituted = _interpolate_value(
                        all_values[ref_key],
                        section_name,
                        all_values,
                        visiting,
                        sections
                    )
                finally:
                    visiting.discard(cycle_key)

                result.append(substituted)

            i = end + 1
        else:
            result.append(value[i])
            i += 1

    return ''.join(result)
