def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Sort and remove duplicates
    unique_nums = sorted(set(nums))

    if not unique_nums:
        return ""

    result = []
    start = unique_nums[0]
    prev = unique_nums[0]

    for curr in unique_nums[1:]:
        if curr == prev + 1:
            prev = curr
        else:
            # Process the completed run
            if prev - start >= 2:
                result.append(f"{start}..{prev}")
            else:
                result.extend(str(x) for x in range(start, prev + 1))
            start = curr
            prev = curr

    # Process the final run
    if prev - start >= 2:
        result.append(f"{start}..{prev}")
    else:
        result.extend(str(x) for x in range(start, prev + 1))

    return ",".join(result)
